parameters.jsCode:
// Define quais pastas do repositorio devem entrar na contagem TOTAL de casos
// de teste do projeto. Antes só existia "/tests" (hardcoded no nó "Listar
// Arquivos de Teste"), por isso a pasta "/tests_performance" nunca era
// buscada nem contada no relatório. Para adicionar/remover uma pasta da
// contagem, basta editar esta lista.
return [
  { json: { pasta: "tests" } }
];

// Conta o total geral de casos de teste que o projeto possui HOJE, considerando
// todos os arquivos .robot das pastas /tests e /tests_performance na branch
// develop (já inclui os casos novos identificados neste mesmo período, pois eles
// já estão na branch).
//
// CORREÇÕES aplicadas nesta versão (motivo da divergência 355 x 359 apontada
// pelo QA ao comparar com a busca "@GTPDV" feita direto no VSCode):
//
// 1) A pasta "/tests_performance" não era buscada (só "/tests" existia no nó
//    "Listar Arquivos de Teste"), então os casos de lá nunca entravam na conta.
//    Corrigido no nó "Definir Pastas de Teste" + "Listar Arquivos de Teste".
//
// 2) O regex antigo exigia um "-" logo após o código do caso, no formato
//    "@GTPDV-T12345 - Descrição". Casos nomeados como
//    "@GTPDV-T12345 Descrição - Subdescrição" (sem hífen logo após o código —
//    é o que acontece, por exemplo, com GTPDV-T19854 e GTPDV-T19865 em
//    14.SelfCheckout_json.robot) nunca eram reconhecidos e ficavam de fora da
//    contagem. O novo regex identifica o caso pela posição no arquivo (início
//    de linha, sem indentação — é assim que o Robot Framework delimita o nome
//    de um caso de teste dentro de "*** Test Cases ***"), e não depende mais
//    de haver um hífen logo em seguida.

const arquivos = $input.all();

// ocorrenciasPorCodigo: Map<codigo, [{arquivo, caminho}]> — usado tanto para
// contar o total de códigos únicos quanto para detectar duplicidade (mesmo
// código aparecendo mais de uma vez, seja duas vezes no mesmo arquivo, seja
// em arquivos diferentes). Um código duplicado é um ID de caso reaproveitado
// por engano e quebra a rastreabilidade do relatório.
const ocorrenciasPorCodigo = new Map();
const porArquivo = [];

// Auditoria de tags obrigatórias: TODO caso de teste do projeto (não só os
// novos do período) precisa ter uma tag de criticidade (baixo/medio/alto/
// critico) e a tag "regressivo-completo". Quem não tiver entra nestas listas
// e vira alerta no relatório.
const CRITICIDADES_VALIDAS = ["baixo", "medio", "alto", "critico"];
const casosSemCriticidade = [];
const casosSemRegressivoCompleto = [];

// =====================================================================
// NOVO: extração de bug via [Documentation]. Padrão no repositório:
//   [Documentation]    [Bug]     DVAROMNIP-1234:  Título da issue
// Pode vir com continuação Robot Framework ("..." na(s) linha(s)
// seguinte(s)) quando a documentação é multi-linha. Regra confirmada
// com o QA: no máximo 1 bug por caso de teste. Roda sobre TODO o
// projeto (não só os casos novos do período), mesmo padrão já usado
// para "casosSemCriticidade"/"casosSemRegressivoCompleto" acima.
// =====================================================================
const RE_BUG = /\[Bug\]\s+DVAROMNIP-(\d+):\s*(.+)/i;

function extrairInfoBug(bloco) {
    const linhasBloco = bloco.split(/\r?\n/);
    const indiceDoc = linhasBloco.findIndex((linha) => /^\s*\[Documentation\]/i.test(linha));

    if (indiceDoc === -1) return null;

    const partesDoc = [linhasBloco[indiceDoc].replace(/^\s*\[Documentation\]\s*/i, "")];

    for (let i = indiceDoc + 1; i < linhasBloco.length; i++) {
        const continuacao = linhasBloco[i].match(/^\s*\.\.\.\s?(.*)$/);
        if (!continuacao) break;
        partesDoc.push(continuacao[1]);
    }

    const documentacao = partesDoc.join("\n");
    const bugMatch = documentacao.match(RE_BUG);

    if (!bugMatch) return null;

    return {
        issue: "DVAROMNIP-" + bugMatch[1],
        titulo_issue: bugMatch[2].trim()
    };
}

// codigo -> { codigo, issue, titulo_issue, arquivo, caminho, linha }
// para casos de teste cujo [Documentation] referencia um bug aberto.
const casosComBugPorCodigo = new Map();

for (const item of arquivos) {
    const conteudo = item.json.content || "";

    // "path" vem preenchido pela própria API do Azure DevOps na resposta do
    // download (fallback para "caminho_arquivo" caso a API não devolva path).
    const caminho = item.json.path || item.json.caminho_arquivo || "desconhecido";

    const partes = caminho.split("/").filter(Boolean);
    const nomeArquivo = partes[partes.length - 1] || caminho;
    const pasta = partes.length > 1 ? partes[partes.length - 2] : "";

    // Nome de um caso de teste = início de linha, sem indentação, opcionalmente
    // com "@" na frente, seguido do código GTPDV-Txxxx — independente do que
    // vem depois na mesma linha (hífen ou não).
    const encontrados = [...conteudo.matchAll(/^@?(GTPDV-T\d+)\b/gm)];

    const codigosDoArquivo = new Set();

    encontrados.forEach((match, idx) => {
        const codigo = match[1];
        codigosDoArquivo.add(codigo);

        // Bloco do caso: do início deste match até o início do próximo caso
        // (ou fim do arquivo) — mesma lógica usada em "Enriquecer Caso de
        // Teste", só que aqui aplicada a TODOS os casos do arquivo de uma vez.
        const inicio = match.index;
        const fim = encontrados[idx + 1]?.index ?? conteudo.length;
        const bloco = conteudo.substring(inicio, fim);

        // Número da linha (1-indexado) onde o caso começa no arquivo, para dar
        // ao QA o "arquivo:linha" exato a corrigir (contagem de \n antes do match).
        const linha = conteudo.substring(0, inicio).split("\n").length;

        if (!ocorrenciasPorCodigo.has(codigo)) ocorrenciasPorCodigo.set(codigo, []);
        ocorrenciasPorCodigo.get(codigo).push({ arquivo: nomeArquivo, caminho, linha });

        const tagsMatch = bloco.match(/\[Tags\](.*)/);
        const tags = tagsMatch
            ? tagsMatch[1].trim().split(/\s{2,}|\t+/).filter(Boolean)
            : [];
        const linhaTags = tagsMatch ? tagsMatch[1].trim() : "(sem linha [Tags])";

        const temCriticidade = tags.some((t) => CRITICIDADES_VALIDAS.includes(t));
        const temRegressivoCompleto = tags.includes("regressivo-completo");

        if (!temCriticidade) {
            casosSemCriticidade.push({ codigo, arquivo: nomeArquivo, caminho, linha, linhaTags });
        }
        if (!temRegressivoCompleto) {
            casosSemRegressivoCompleto.push({ codigo, arquivo: nomeArquivo, caminho, linha, linhaTags });
        }

        if (!casosComBugPorCodigo.has(codigo)) {
            const infoBug = extrairInfoBug(bloco);
            if (infoBug) {
                casosComBugPorCodigo.set(codigo, {
                    codigo,
                    issue: infoBug.issue,
                    titulo_issue: infoBug.titulo_issue,
                    arquivo: nomeArquivo,
                    caminho,
                    linha
                });
            }
        }
    });

    porArquivo.push({
        arquivo: nomeArquivo,
        pasta,
        caminho,
        quantidade: codigosDoArquivo.size
    });
}

// Códigos que apareceram mais de uma vez (mesmo arquivo ou arquivos
// diferentes) no projeto inteiro.
const codigosDuplicados = [...ocorrenciasPorCodigo.entries()]
    .filter(([, ocorrencias]) => ocorrencias.length > 1)
    .map(([codigo, ocorrencias]) => ({ codigo, ocorrencias }));

// Ordena por pasta e depois por nome do arquivo (numérico), para bater com a
// árvore de pastas do repositório e facilitar a conferência manual.
porArquivo.sort((a, b) => {
    if (a.pasta !== b.pasta) return a.pasta.localeCompare(b.pasta);
    return a.arquivo.localeCompare(b.arquivo, undefined, { numeric: true });
});

const totalPorPastaMapa = {};
for (const linha of porArquivo) {
    totalPorPastaMapa[linha.pasta] = (totalPorPastaMapa[linha.pasta] || 0) + linha.quantidade;
}

const totalPorPasta = Object.entries(totalPorPastaMapa).map(([pasta, quantidade]) => ({
    pasta,
    quantidade
}));

return [
    {
        json: {
            total_geral: ocorrenciasPorCodigo.size,
            por_suite: porArquivo,
            total_por_pasta: totalPorPasta,
            codigos_duplicados: codigosDuplicados,
            casos_sem_criticidade: casosSemCriticidade,
            casos_sem_regressivo_completo: casosSemRegressivoCompleto,
            // NOVO: casos do projeto inteiro com bug aberto referenciado no
            // [Documentation] (issue DVAROMNIP).
            casos_com_bug: [...casosComBugPorCodigo.values()].sort((a, b) =>
                a.codigo.localeCompare(b.codigo, "pt-BR", { numeric: true })
            )
        }
    }
];

// Pega a lista completa de itens (arquivos e pastas) retornada pela API do
// Azure DevOps. O nó anterior ("Listar Arquivos de Teste") agora roda uma vez
// para CADA pasta configurada em "Definir Pastas de Teste" (ex.: "tests" e
// "tests_performance"), então recebemos aqui um item de entrada por pasta, e
// precisamos combinar o resultado de todas elas em vez de olhar somente para
// o primeiro item (bug anterior: só a 1ª pasta buscada era considerada).
const arquivosRobot = [];

for (const entrada of $input.all()) {
    const itens = entrada.json.value || [];

    const robots = itens.filter(item =>
        item.gitObjectType === "blob" &&
        (item.path || "").toLowerCase().endsWith(".robot")
    );

    arquivosRobot.push(...robots);
}

return arquivosRobot.map(item => ({
    json: {
        caminho_arquivo: item.path
    }
}));

// =====================================================================================
// NÓ: Gerar Relatório HTML (versão E-MAIL)
// TIPO: Code Node (JavaScript) - n8n
// ENTRADA ESPERADA: item.json vindo do nó "Preparar Dados para Relatório"
//   { periodo_criacao_inicio, periodo_criacao_fim, resumo, rankings, indicadores, recursos, casos, casos_removidos, insights }
// SAÍDA: { json: { html, periodo_criacao_inicio, periodo_criacao_fim, total_casos, total_casos_removidos } }
//
// POR QUE UMA VERSÃO DIFERENTE?
// Clientes de e-mail (Outlook, Gmail, etc.) usam motores de renderização limitados:
//   - Outlook usa o motor do Word (não suporta grid, flexbox, position, :hover, var())
//   - Gmail remove tags <style> em alguns contextos (webmail)
// Por isso, este nó usa APENAS:
//   - Tabelas HTML (<table>) para layout
//   - Estilos INLINE (style="...") em cada elemento
//   - Cores fixas (sem variáveis CSS)
// Isso garante que o relatório chegue formatado corretamente para os gestores,
// independente do cliente de e-mail usado.
// =====================================================================================

// -------------------------------------------------------------------------------------
// 1. LEITURA DOS DADOS DE ENTRADA
// -------------------------------------------------------------------------------------
const dados = $input.first().json;

const {
  periodo_criacao_inicio = "",
  periodo_criacao_fim = "",
  resumo = {},
  rankings = {},
  indicadores = {},
  recursos = {},
  casos = [],
  casos_removidos = [],
  insights = [],
  por_suite = [],
  total_por_pasta = [],
  casos_sem_criticidade = [],
  casos_sem_regressivo_completo = [],
  casos_com_bug = [],
  codigos_duplicados = []
} = dados;

// =====================================================================================
// 2. PALETA DE CORES (centralizada para fácil ajuste futuro)
// =====================================================================================
const CORES = {
  primaria: "#4f46e5",
  primariaEscura: "#3730a3",
  fundoPagina: "#eef0f5",
  fundoCard: "#ffffff",
  textoPrimario: "#1a1d29",
  textoSecundario: "#6b7280",
  borda: "#e5e7eb",
  fundoDestaque: "#eef2ff",
  verde: "#16a34a",
  verdeFundo: "#dcfce7",
  vermelho: "#dc2626",
  vermelhoFundo: "#fee2e2",
  laranja: "#ea580c",
  laranjaFundo: "#ffedd5",
  amarelo: "#a16207",
  amareloFundo: "#fef9c3",
  cinzaFundo: "#e5e7eb",
  cinzaTexto: "#374151"
};

const FONTE = "Arial, Helvetica, sans-serif";
const LARGURA_TOTAL = 640; // largura segura para a maioria dos clientes de e-mail

// =====================================================================================
// 3. FUNÇÕES UTILITÁRIAS
// =====================================================================================

function escapeHtml(texto) {
  if (texto === null || texto === undefined) return "";
  return String(texto)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
}

/** Formata uma data ISO (ex: 2026-07-16T00:00:00.000Z) para dd/mm/aaaa. */
function formatarData(iso) {
  if (!iso) return "";
  const d = new Date(iso);
  if (isNaN(d.getTime())) return String(iso);
  return d.toLocaleDateString("pt-BR");
}

/** Retorna { texto, corTexto, corFundo } para badges de criticidade. */
function estiloCriticidade(criticidade) {
  const chave = String(criticidade || "").toLowerCase();
  const mapa = {
    critico: { cor: CORES.vermelho, fundo: CORES.vermelhoFundo },
    alto: { cor: CORES.laranja, fundo: CORES.laranjaFundo },
    medio: { cor: CORES.amarelo, fundo: CORES.amareloFundo },
    baixo: { cor: CORES.verde, fundo: CORES.verdeFundo }
  };
  return mapa[chave] || { cor: CORES.cinzaTexto, fundo: CORES.cinzaFundo };
}

/** Retorna { cor, fundo } para badges de complexidade. */
function estiloComplexidade(complexidade) {
  const chave = String(complexidade || "").toLowerCase();
  const mapa = {
    "muito alta": { cor: CORES.vermelho, fundo: CORES.vermelhoFundo },
    "alta": { cor: CORES.laranja, fundo: CORES.laranjaFundo },
    "média": { cor: CORES.amarelo, fundo: CORES.amareloFundo },
    "media": { cor: CORES.amarelo, fundo: CORES.amareloFundo },
    "baixa": { cor: CORES.verde, fundo: CORES.verdeFundo }
  };
  return mapa[chave] || { cor: CORES.cinzaTexto, fundo: CORES.cinzaFundo };
}

function maiorQuantidade(lista) {
  if (!lista || lista.length === 0) return 1;
  return Math.max(...lista.map((item) => item.quantidade || 0), 1);
}

/** Gera um badge (pílula colorida) usando tabela inline, seguro para Outlook. */
function gerarBadge(texto, cor, fundo) {
  return `
    <span style="display:inline-block; padding:3px 10px; border-radius:12px;
      font-size:12px; font-weight:bold; color:${cor}; background-color:${fundo};
      text-transform:capitalize; white-space:nowrap; font-family:${FONTE};">
      ${escapeHtml(texto)}
    </span>
  `;
}

/** Gera uma barra de progresso baseada em tabela (compatível com Outlook).
 *  CORREÇÃO: com percentual=0, um <td width="0%"> ainda com conteúdo (&nbsp;)
 *  não colapsa de forma confiável em vários clientes de e-mail — o motor do
 *  Word (Outlook) e alguns webmails ignoram width="0%" e distribuem o espaço
 *  50/50 entre as duas células da tabela, fazendo a barra aparecer "pela
 *  metade" mesmo sem nenhum caso. Por isso, quando p=0, a célula colorida
 *  nem é criada — a tabela vira uma única célula de fundo, garantindo barra
 *  visualmente vazia em qualquer cliente. */
function gerarBarra(percentual, corBarra, corFundo, altura) {
  const p = Math.max(0, Math.min(100, Math.round(percentual)));

  if (p === 0) {
    return `
      <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"
        style="border-collapse:collapse; background-color:${corFundo}; border-radius:6px; overflow:hidden;">
        <tr>
          <td height="${altura}" style="font-size:1px; line-height:1px;">&nbsp;</td>
        </tr>
      </table>
    `;
  }

  return `
    <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"
      style="border-collapse:collapse; background-color:${corFundo}; border-radius:6px; overflow:hidden;">
      <tr>
        <td width="${p}%" height="${altura}" bgcolor="${corBarra}" style="width:${p}%; font-size:1px; line-height:1px;">&nbsp;</td>
        <td style="font-size:1px; line-height:1px;">&nbsp;</td>
      </tr>
    </table>
  `;
}

// =====================================================================================
// 4. GERAÇÃO DE BLOCOS (cada função monta uma seção, sempre com tabelas + inline CSS)
// =====================================================================================

/** Tabela com o total de casos de teste por suíte (arquivo .robot), calculado
 *  ao vivo em todo o projeto (pastas /tests e /tests_performance). Foi
 *  adicionada a pedido do QA, para bater de forma rápida com a árvore de
 *  pastas do repositório e detectar divergências de contagem por arquivo. */
function gerarTabelaPorSuite() {
  if (!por_suite || por_suite.length === 0) return "";

  const cardsPasta = (total_por_pasta || [])
    .map(
      (p) => `
      <td width="50%" style="padding:6px;" valign="top">
        <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"
          style="background-color:${CORES.fundoCard}; border:1px solid ${CORES.borda};
          border-left:4px solid ${CORES.primaria}; border-radius:6px;">
          <tr>
            <td style="padding:14px 16px; font-family:${FONTE};">
              <div style="font-size:11px; color:${CORES.textoSecundario}; letter-spacing:0.03em; margin-bottom:4px;">
                PASTA "${escapeHtml(p.pasta || "-")}"
              </div>
              <div style="font-size:17px; font-weight:bold; color:${CORES.textoPrimario};">
                ${p.quantidade} caso(s)
              </div>
            </td>
          </tr>
        </table>
      </td>
    `
    )
    .join("");

  const linhas = por_suite
    .map((linha, index) => {
      const bgLinha = index % 2 === 0 ? "#ffffff" : "#fafbff";
      return `
        <tr style="background-color:${bgLinha};">
          <td style="padding:7px 10px; font-family:${FONTE}; font-size:11px; color:${CORES.textoPrimario}; border-bottom:1px solid ${CORES.borda}; white-space:nowrap;">
            ${escapeHtml(linha.arquivo)}
          </td>
          <td style="padding:7px 10px; font-family:${FONTE}; font-size:11px; color:${CORES.textoSecundario}; border-bottom:1px solid ${CORES.borda}; white-space:nowrap;">
            ${escapeHtml(linha.pasta)}
          </td>
          <td align="right" style="padding:7px 10px; font-family:${FONTE}; font-size:12px; font-weight:bold; color:${CORES.primaria}; border-bottom:1px solid ${CORES.borda};">
            ${linha.quantidade}
          </td>
        </tr>
      `;
    })
    .join("");

  const somaPorSuite = por_suite.reduce((soma, l) => soma + (l.quantidade || 0), 0);
  const observacaoDivergencia =
    somaPorSuite !== (resumo.total_geral_projeto ?? somaPorSuite)
      ? `<div style="font-family:${FONTE}; font-size:10px; color:${CORES.laranja}; margin-top:6px;">
           &#9888; A soma por suíte (${somaPorSuite}) difere do total geral único (${resumo.total_geral_projeto}).
           Isso acontece se o mesmo código de caso aparecer em mais de um arquivo — vale conferir.
         </div>`
      : "";

  return `
    <tr>
      <td style="padding:16px 24px 8px; font-family:${FONTE};">
        <div style="font-size:16px; font-weight:bold; color:${CORES.textoPrimario}; margin-bottom:10px;">
          Casos de Teste por Suíte (Total no Projeto)
        </div>

        ${
          cardsPasta
            ? `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin-bottom:10px;"><tr>${cardsPasta}</tr></table>`
            : ""
        }

        <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"
          style="background-color:${CORES.fundoCard}; border:1px solid ${CORES.borda}; border-radius:6px; overflow:hidden;">
          <tr style="background-color:#f8f9fc;">
            <th align="left" style="padding:9px 10px; font-family:${FONTE}; font-size:10px; text-transform:uppercase; color:${CORES.textoSecundario}; border-bottom:2px solid ${CORES.borda};">Suíte (arquivo .robot)</th>
            <th align="left" style="padding:9px 10px; font-family:${FONTE}; font-size:10px; text-transform:uppercase; color:${CORES.textoSecundario}; border-bottom:2px solid ${CORES.borda};">Pasta</th>
            <th align="right" style="padding:9px 10px; font-family:${FONTE}; font-size:10px; text-transform:uppercase; color:${CORES.textoSecundario}; border-bottom:2px solid ${CORES.borda};">Qtd. Casos</th>
          </tr>
          ${linhas}
          <tr style="background-color:${CORES.fundoDestaque};">
            <td colspan="2" style="padding:9px 10px; font-family:${FONTE}; font-size:12px; font-weight:bold; color:${CORES.textoPrimario};">TOTAL GERAL</td>
            <td align="right" style="padding:9px 10px; font-family:${FONTE}; font-size:13px; font-weight:bold; color:${CORES.primaria};">${somaPorSuite}</td>
          </tr>
        </table>
        ${observacaoDivergencia}
      </td>
    </tr>
  `;
}

/** Cabeçalho do relatório. */
function gerarCabecalho() {
  return `
    <tr>
      <td style="background-color:${CORES.primariaEscura}; padding:28px 32px; border-radius:8px 8px 0 0;">
        <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0">
          <tr>
            <td style="font-family:${FONTE}; color:#ffffff; font-size:22px; font-weight:bold;">
              Relatório de Cobertura de Testes Automatizados – SelfCheckout
            </td>
          </tr>
          <tr>
            <td style="font-family:${FONTE}; color:#dbe0ff; font-size:13px; padding-top:6px;">
              Período: ${escapeHtml(formatarData(periodo_criacao_inicio))} até ${escapeHtml(formatarData(periodo_criacao_fim))}
            </td>
          </tr>
        </table>
      </td>
    </tr>
  `;
}

/** Cards de indicadores gerais, em formato de tabela 2 colunas (empilha bem no mobile). */
function gerarCardsIndicadores() {
  const cards = [
    { titulo: "NOVOS CASOS NO PERÍODO", valor: resumo.total_casos ?? "-", cor: "#3b82f6" },
    { titulo: "TOTAL GERAL NO PROJETO", valor: resumo.total_geral_projeto ?? "-", cor: "#0ea5e9" },
    { titulo: "CASOS REMOVIDOS", valor: resumo.total_casos_removidos ?? 0, cor: "#dc2626" },
    {
      titulo: "PRINCIPAL FUNCIONALIDADE",
      valor: resumo.principal_funcionalidade ?? "-",
      extra: resumo.principal_funcionalidade_qtd ? `${resumo.principal_funcionalidade_qtd} caso(s)` : "",
      cor: "#8b5cf6"
    },
    { titulo: "PRINCIPAL CRITICIDADE", valor: resumo.principal_criticidade ?? "-", cor: "#ef4444" },
    { titulo: "PRINCIPAL REGRESSÃO", valor: resumo.principal_regressao ?? "-", cor: "#22c55e" }
  ];

  // Monta em pares de 2 colunas por linha (mais seguro que 4 colunas em telas pequenas)
  let linhas = "";
  for (let i = 0; i < cards.length; i += 2) {
    const par = cards.slice(i, i + 2);
    const celulas = par
      .map(
        (c) => `
        <td width="50%" style="padding:6px;" valign="top">
          <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"
            style="background-color:${CORES.fundoCard}; border:1px solid ${CORES.borda};
            border-left:4px solid ${c.cor}; border-radius:6px;">
            <tr>
              <td style="padding:14px 16px; font-family:${FONTE};">
                <div style="font-size:11px; color:${CORES.textoSecundario}; letter-spacing:0.03em; margin-bottom:4px;">
                  ${escapeHtml(c.titulo)}
                </div>
                <div style="font-size:17px; font-weight:bold; color:${CORES.textoPrimario}; text-transform:capitalize;">
                  ${escapeHtml(c.valor)}
                </div>
                ${
                  c.extra
                    ? `<div style="font-size:11px; color:${CORES.textoSecundario}; margin-top:2px;">${escapeHtml(c.extra)}</div>`
                    : ""
                }
              </td>
            </tr>
          </table>
        </td>
      `
      )
      .join("");

    // Se sobrar célula ímpar, completa com célula vazia
    const preencher = par.length === 1 ? `<td width="50%" style="padding:6px;">&nbsp;</td>` : "";

    linhas += `<tr>${celulas}${preencher}</tr>`;
  }

  return `
    <tr>
      <td style="padding:24px 24px 8px; font-family:${FONTE};">
        <div style="font-size:16px; font-weight:bold; color:${CORES.textoPrimario}; margin-bottom:10px;">
          Indicadores Gerais
        </div>
        <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0">
          ${linhas}
        </table>
      </td>
    </tr>
  `;
}

/** Um bloco de ranking (lista com barras). Reaproveitado para todas as categorias. */
function gerarBlocoRanking(titulo, lista) {
  if (!lista || lista.length === 0) {
    return `<div style="font-family:${FONTE}; font-size:13px; color:${CORES.textoSecundario}; font-style:italic;">Sem dados.</div>`;
  }

  const maior = maiorQuantidade(lista);
  const ordenado = [...lista].sort((a, b) => (b.quantidade || 0) - (a.quantidade || 0));

  const linhas = ordenado
    .map((item) => {
      const percentual = ((item.quantidade || 0) / maior) * 100;
      return `
        <tr>
          <td style="padding:6px 0; font-family:${FONTE};">
            <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0">
              <tr>
                <td style="font-size:12px; color:${CORES.textoPrimario}; text-transform:capitalize; padding-bottom:3px;">
                  ${escapeHtml(item.nome)}
                  <span style="float:right; font-weight:bold; color:${CORES.primaria};">${escapeHtml(item.quantidade)}</span>
                </td>
              </tr>
              <tr>
                <td>${gerarBarra(percentual, CORES.primaria, "#eef0f5", 7)}</td>
              </tr>
            </table>
          </td>
        </tr>
      `;
    })
    .join("");

  return `
    <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0">
      <tr><td style="font-family:${FONTE}; font-size:13px; font-weight:bold; color:${CORES.textoPrimario}; padding-bottom:8px;">${escapeHtml(titulo)}</td></tr>
      ${linhas}
    </table>
  `;
}

/** Seção com os 4 rankings, organizados em 2 colunas. */
function gerarSecaoRankings() {
  const blocos = [
    gerarBlocoRanking("Por Funcionalidade", rankings.funcionalidades),
    gerarBlocoRanking("Por Criticidade", rankings.criticidades),
    gerarBlocoRanking("Por Regressão", rankings.regressoes),
    gerarBlocoRanking("Por Complexidade", rankings.complexidades)
  ];

  let linhas = "";
  for (let i = 0; i < blocos.length; i += 2) {
    const par = blocos.slice(i, i + 2);
    linhas += `
      <tr>
        <td width="50%" valign="top" style="padding:10px; background-color:${CORES.fundoCard}; border:1px solid ${CORES.borda}; border-radius:6px;">
          ${par[0]}
        </td>
        <td width="12"></td>
        <td width="50%" valign="top" style="padding:10px; background-color:${CORES.fundoCard}; border:1px solid ${CORES.borda}; border-radius:6px;">
          ${par[1] || "&nbsp;"}
        </td>
      </tr>
      <tr><td colspan="3" height="12"></td></tr>
    `;
  }

  return `
    <tr>
      <td style="padding:16px 24px 8px; font-family:${FONTE};">
        <div style="font-size:16px; font-weight:bold; color:${CORES.textoPrimario}; margin-bottom:10px;">
          Rankings
        </div>
        <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0">
          ${linhas}
        </table>
      </td>
    </tr>
  `;
}

/** Indicadores técnicos (percentual de uso de cada recurso). */
function gerarIndicadoresTecnicos() {
  const chaves = Object.keys(indicadores);
  if (chaves.length === 0) return "";

  const linhas = chaves
    .sort((a, b) => (indicadores[b] || 0) - (indicadores[a] || 0))
    .map((chave) => {
      const percentual = indicadores[chave] ?? 0;
      const qtd = recursos[chave] ?? "-";
      const corBarra = percentual >= 80 ? CORES.verde : percentual >= 50 ? CORES.laranja : CORES.vermelho;

      return `
        <tr>
          <td style="padding:8px 0; font-family:${FONTE};">
            <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0">
              <tr>
                <td style="font-size:12px; color:${CORES.textoPrimario}; text-transform:capitalize; padding-bottom:3px;">
                  ${escapeHtml(chave.replace(/_/g, " "))}
                  <span style="float:right; color:${CORES.textoSecundario};">
                    <b style="color:${CORES.textoPrimario};">${percentual}%</b> (${escapeHtml(qtd)} casos)
                  </span>
                </td>
              </tr>
              <tr>
                <td>${gerarBarra(percentual, corBarra, "#eef0f5", 8)}</td>
              </tr>
            </table>
          </td>
        </tr>
      `;
    })
    .join("");

  return `
    <tr>
      <td style="padding:16px 24px 8px; font-family:${FONTE};">
        <div style="font-size:16px; font-weight:bold; color:${CORES.textoPrimario}; margin-bottom:10px;">
          Indicadores Técnicos
        </div>
        <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"
          style="background-color:${CORES.fundoCard}; border:1px solid ${CORES.borda}; border-radius:6px;">
          <tr><td style="padding:14px 16px;">
            <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0">
              ${linhas}
            </table>
          </td></tr>
        </table>
      </td>
    </tr>
  `;
}

/** Insights executivos, em formato de lista destacada. */
function gerarInsights() {
  if (!insights || insights.length === 0) return "";

  const linhas = insights
    .map(
