/** Verificação de códigos de caso de teste duplicados. Ao contrário dos outros
 *  alertas (que somem quando não há problema), este SEMPRE aparece no
 *  relatório — como confirmação positiva quando está tudo certo, ou como
 *  tabela detalhada (uma linha por ocorrência) quando há duplicidade. */
function gerarCodigosDuplicados() {
  if (!codigos_duplicados || codigos_duplicados.length === 0) {
    return `
      <tr>
        <td style="padding:16px 24px 8px; font-family:${FONTE};">
          <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"
            style="background-color:${CORES.verdeFundo}; border-left:3px solid ${CORES.verde}; border-radius:4px;">
            <tr>
              <td style="padding:10px 14px; font-family:${FONTE}; font-size:13px; color:${CORES.textoPrimario};">
                &#9989; Nenhum código de caso de teste duplicado encontrado no repositório.
              </td>
            </tr>
          </table>
        </td>
      </tr>
    `;
  }

  const linhas = codigos_duplicados
    .map((dup) => {
      const total = dup.ocorrencias.length;
      return dup.ocorrencias
        .map((ocorrencia, idx) => {
          const bgLinha = idx % 2 === 0 ? "#fffbfb" : "#fff5f5";
          const arquivoLinha = ocorrencia.linha ? `${ocorrencia.caminho}:${ocorrencia.linha}` : ocorrencia.caminho;

          return `
            <tr style="background-color:${bgLinha};">
              <td style="padding:8px 10px; font-family:${FONTE}; font-size:11px; color:${CORES.vermelho}; font-weight:bold; border-bottom:1px solid ${CORES.borda}; white-space:nowrap;">
                ${idx === 0 ? escapeHtml(dup.codigo) : ""}
              </td>
              <td style="padding:8px 10px; font-family:${FONTE}; font-size:11px; color:${CORES.textoSecundario}; border-bottom:1px solid ${CORES.borda}; white-space:nowrap;">
                Ocorrência ${idx + 1} de ${total}
              </td>
              <td style="padding:8px 10px; font-family:${FONTE}; font-size:11px; color:${CORES.textoPrimario}; border-bottom:1px solid ${CORES.borda};">
                ${escapeHtml(arquivoLinha)}
              </td>
            </tr>
          `;
        })
        .join("");
    })
    .join("");

  return `
    <tr>
      <td style="padding:16px 24px 24px; font-family:${FONTE};">
        <div style="font-size:16px; font-weight:bold; color:${CORES.vermelho}; margin-bottom:6px;">
          &#9888; Códigos de Caso de Teste Duplicados (${codigos_duplicados.length})
        </div>
        <div style="font-size:12px; color:${CORES.textoSecundario}; margin-bottom:10px; line-height:1.5;">
          O mesmo código de caso de teste foi encontrado mais de uma vez no repositório (no mesmo arquivo ou em arquivos diferentes). Isso quebra a rastreabilidade do relatório — ajuste um dos casos para usar um código único.
        </div>
        <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"
          style="background-color:${CORES.fundoCard}; border:1px solid ${CORES.vermelhoFundo}; border-radius:6px; overflow:hidden;">
          <tr style="background-color:${CORES.vermelhoFundo};">
            <th align="left" style="padding:9px 10px; font-family:${FONTE}; font-size:10px; text-transform:uppercase; color:${CORES.vermelho}; border-bottom:2px solid ${CORES.borda};">Código</th>
            <th align="left" style="padding:9px 10px; font-family:${FONTE}; font-size:10px; text-transform:uppercase; color:${CORES.vermelho}; border-bottom:2px solid ${CORES.borda};">Ocorrência</th>
            <th align="left" style="padding:9px 10px; font-family:${FONTE}; font-size:10px; text-transform:uppercase; color:${CORES.vermelho}; border-bottom:2px solid ${CORES.borda};">Arquivo : Linha</th>
          </tr>
          ${linhas}
        </table>
      </td>
    </tr>
  `;
}

/** Tabela de alerta genérica para casos de teste com tag obrigatória ausente.
 *  Reaproveita o mesmo padrão visual de "Casos Removidos do Repositório"
 *  (card com cabeçalho colorido + tabela), só que na cor laranja (aviso),
 *  não vermelha (que já é usada para casos removidos). */
function gerarTabelaAlertaTags(titulo, descricao, lista) {
  if (!lista || lista.length === 0) return "";

  const linhas = lista
    .map((item, index) => {
      const bgLinha = index % 2 === 0 ? "#fffaf5" : "#fff6ec";
      const arquivoLinha = item.linha ? `${item.caminho}:${item.linha}` : item.caminho || "-";

      return `
        <tr style="background-color:${bgLinha};">
          <td style="padding:8px 10px; font-family:${FONTE}; font-size:11px; color:${CORES.primaria}; font-weight:bold; border-bottom:1px solid ${CORES.borda}; white-space:nowrap;">
            ${escapeHtml(item.codigo)}
          </td>
          <td style="padding:8px 10px; font-family:${FONTE}; font-size:11px; color:${CORES.textoPrimario}; border-bottom:1px solid ${CORES.borda}; white-space:nowrap;">
            ${escapeHtml(arquivoLinha)}
          </td>
          <td style="padding:8px 10px; font-family:${FONTE}; font-size:11px; color:${CORES.textoSecundario}; border-bottom:1px solid ${CORES.borda};">
            ${escapeHtml(item.linhaTags || "-")}
          </td>
        </tr>
      `;
    })
    .join("");

  return `
    <tr>
      <td style="padding:16px 24px 24px; font-family:${FONTE};">
        <div style="font-size:16px; font-weight:bold; color:${CORES.laranja}; margin-bottom:6px;">
          &#9888; ${escapeHtml(titulo)} (${lista.length})
        </div>
        <div style="font-size:12px; color:${CORES.textoSecundario}; margin-bottom:10px; line-height:1.5;">
          ${descricao}
        </div>
        <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"
          style="background-color:${CORES.fundoCard}; border:1px solid ${CORES.laranjaFundo}; border-radius:6px; overflow:hidden;">
          <tr style="background-color:${CORES.laranjaFundo};">
            <th align="left" style="padding:9px 10px; font-family:${FONTE}; font-size:10px; text-transform:uppercase; color:${CORES.laranja}; border-bottom:2px solid ${CORES.borda};">Código</th>
            <th align="left" style="padding:9px 10px; font-family:${FONTE}; font-size:10px; text-transform:uppercase; color:${CORES.laranja}; border-bottom:2px solid ${CORES.borda};">Arquivo : Linha</th>
            <th align="left" style="padding:9px 10px; font-family:${FONTE}; font-size:10px; text-transform:uppercase; color:${CORES.laranja}; border-bottom:2px solid ${CORES.borda};">Linha [Tags]</th>
          </tr>
          ${linhas}
        </table>
      </td>
    </tr>
  `;
}

/** Casos do projeto sem nenhuma tag de criticidade (baixo/medio/alto/critico). */
function gerarCasosSemCriticidade() {
  return gerarTabelaAlertaTags(
    "Casos sem tag de criticidade",
