    casos_sem_criticidade
  );
}

/** Casos do projeto sem a tag "regressivo-completo". */
function gerarCasosSemRegressivoCompleto() {
  return gerarTabelaAlertaTags(
    'Casos sem "regressivo-completo"',
    'Todo caso de teste precisa da tag <b>regressivo-completo</b> (mesmo que também tenha <b>mini-regressivo</b>). Sem ela, o caso fica de fora de qualquer execução <code>--include regressivo-completo</code>.',
