}

/** Tabela completa de casos (versão resumida: colunas essenciais para leitura no e-mail). */
function gerarTabelaCasos() {
  if (!casos || casos.length === 0) return "";

  const linhas = casos
    .map((caso, index) => {
      const bgLinha = index % 2 === 0 ? "#ffffff" : "#fafbff";
      // Sem tag de criticidade = alerta (fundo cinza + texto vermelho, combinação
      // que nenhum nível real de criticidade usa, para não ser confundida com
      // "crítico" de verdade).
      const critStyle = caso.criticidade
        ? estiloCriticidade(caso.criticidade)
        : { cor: CORES.vermelho, fundo: CORES.cinzaFundo };
      const compStyle = estiloComplexidade(caso.complexidade);
      const temRegressao = Array.isArray(caso.regressao) && caso.regressao.length > 0;
      const temRegressivoCompleto = Array.isArray(caso.regressao) && caso.regressao.includes("regressivo-completo");
      const regressoes = temRegressao ? caso.regressao.join(", ") : "-";

      return `
        <tr style="background-color:${bgLinha};">
          <td style="padding:8px 10px; font-family:${FONTE}; font-size:11px; color:${CORES.primaria}; font-weight:bold; border-bottom:1px solid ${CORES.borda}; white-space:nowrap;">
            ${escapeHtml(caso.codigo)}
          </td>
          <td style="padding:8px 10px; font-family:${FONTE}; font-size:11px; color:${CORES.textoPrimario}; border-bottom:1px solid ${CORES.borda};">
            ${escapeHtml(caso.descricao)}
          </td>
          <td style="padding:8px 10px; font-family:${FONTE}; font-size:11px; color:${CORES.textoPrimario}; border-bottom:1px solid ${CORES.borda}; white-space:nowrap;">
            ${escapeHtml(caso.funcionalidade)}
          </td>
          <td style="padding:8px 10px; border-bottom:1px solid ${CORES.borda}; white-space:nowrap;">
            ${gerarBadge(caso.criticidade || "sem tag", critStyle.cor, critStyle.fundo)}
          </td>
          <td style="padding:8px 10px; border-bottom:1px solid ${CORES.borda}; white-space:nowrap;">
            ${gerarBadge(caso.complexidade, compStyle.cor, compStyle.fundo)}
          </td>
          <td style="padding:8px 10px; font-family:${FONTE}; font-size:11px; color:${CORES.textoSecundario}; border-bottom:1px solid ${CORES.borda};">
            ${escapeHtml(regressoes)}
            ${
              !temRegressivoCompleto
                ? `<br/><span style="color:${CORES.vermelho}; font-size:10px; font-weight:bold; white-space:nowrap;">&#9888; sem "regressivo-completo"</span>`
                : ""
            }
          </td>
        </tr>
      `;
    })
    .join("");

  return `
    <tr>
      <td style="padding:16px 24px 24px; font-family:${FONTE};">
        <div style="font-size:16px; font-weight:bold; color:${CORES.textoPrimario}; margin-bottom:10px;">
          Tabela Completa de Casos (${casos.length})
        </div>
        <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"
          style="background-color:${CORES.fundoCard}; border:1px solid ${CORES.borda}; border-radius:6px; overflow:hidden;">
