// CORREÇÃO (relatório não saía em períodos sem casos novos):
// Se nenhum commit do período alterar um arquivo .robot, algum nó no meio da
// cadeia de diff (Buscar Alterações do Commit -> ... -> Identificar Novos
// Casos de Teste) fica com 0 itens de entrada e o n8n, por padrão, pula a
// execução desse nó — isso cascateia até "Preparar Dados para Relatório",
// que nunca disparava (0 itens de entrada = nó pulado também).
//
// FIX: habilitei "Always Output Data" (aba Settings do nó) em "Enriquecer
// Caso de Teste" — não em "Classificar Casos de Teste" como na primeira
// tentativa. Motivo: "Classificar Casos de Teste" roda em modo "Run Once for
// Each Item" (usa $input.item.json), e esse modo não lida bem com Always
// Output Data quando não há NENHUM item real — o node tenta rodar por item
// mesmo sem item nenhum e quebra. "Enriquecer Caso de Teste" roda em modo
// "Run Once for All Items" (usa $input.all() num for-loop) — com 0 itens,
// o loop simplesmente não executa e o código retorna [] normalmente, sem
// erro; o Always Output Data então força a emissão de 1 item vazio {},
// que flui tranquilamente pelo "Classificar Casos de Teste" (código
// tolerante a bloco_teste="") e chega aqui sem "codigo"/"tipo_mudanca".
// O filtro abaixo descarta esse item vazio antes de processar — ele nunca é
// contado como um caso novo/removido de verdade.
const todosOsItens = $input.all()
    .map(i => i.json)
    .filter(item => item && item.codigo && item.tipo_mudanca);

// O nó "Identificar Novos Casos de Teste" agora manda dois tipos de item no
// mesmo stream: tipo_mudanca = 'novo' ou 'removido'. Separamos aqui para que
// os rankings/indicadores (funcionalidade, criticidade, complexidade, uso de
// recursos) continuem refletindo apenas os casos novos do período, e não
// misturem com os removidos.
// Deduplica pelo código do caso: o mesmo código pode aparecer mais de uma vez
// no stream do período (ex.: o mesmo arquivo foi tocado por dois commits
// diferentes dentro da janela, ou o código foi reintroduzido em outro
// arquivo). Sem isso, o caso entra duas vezes na tabela e infla indicadores/
// rankings. Mantém a ocorrência mais recente (maior data_commit).
function deduplicarPorCodigo(lista) {
    const mapa = new Map();
    let duplicados = 0;

    for (const caso of lista) {
        if (mapa.has(caso.codigo)) {
            duplicados++;
            const existente = mapa.get(caso.codigo);
            const dataExistente = new Date(existente.data_commit || 0).getTime();
            const dataAtual = new Date(caso.data_commit || 0).getTime();
            if (dataAtual >= dataExistente) mapa.set(caso.codigo, caso);
        } else {
            mapa.set(caso.codigo, caso);
        }
    }

    return { lista: [...mapa.values()], duplicados };
}

const dedupCasos = deduplicarPorCodigo(todosOsItens.filter(c => c.tipo_mudanca !== 'removido'));
const dedupRemovidos = deduplicarPorCodigo(todosOsItens.filter(c => c.tipo_mudanca === 'removido'));

const casos = dedupCasos.lista;
const casos_removidos = dedupRemovidos.lista;
const duplicadosNoPeriodo = dedupCasos.duplicados + dedupRemovidos.duplicados;

function contarPor(lista, campo){

    const mapa = {};

    for(const caso of lista){

        const valor = caso[campo] || "Não informado";

        mapa[valor] = (mapa[valor] || 0) + 1;

    }

    return Object.entries(mapa)
        .sort((a,b)=>b[1]-a[1])
        .map(([nome,quantidade])=>({
            nome,
            quantidade
        }));
}

function contarRegressoes(lista){

    const mapa = {};

    for(const caso of lista){

        for(const reg of (caso.regressao || [])){

            mapa[reg] = (mapa[reg] || 0) + 1;

        }

    }

    return Object.entries(mapa)
        .sort((a,b)=>b[1]-a[1])
        .map(([nome,quantidade])=>({
            nome,
            quantidade
        }));

}

function percentual(valor,total){

