    /embalagem/i.test(bloco);

caso.usa_entrega =
    /entrega|retira/i.test(bloco);

// ===== Complexidade =====

let pontos = 0;

if (caso.usa_json) pontos++;
if (caso.usa_bd) pontos++;
if (caso.usa_frete) pontos++;
if (caso.usa_desconto) pontos++;
if (caso.usa_popup) pontos++;
if (caso.usa_cliente) pontos++;
if (caso.usa_produto) pontos++;
if (caso.usa_pagamento) pontos++;
if (caso.usa_pre_venda) pontos++;
if (caso.usa_embalagem) pontos++;
if (caso.usa_entrega) pontos++;

if (pontos <= 3)
    caso.complexidade = "Baixa";
else if (pontos <= 6)
    caso.complexidade = "Média";
else if (pontos <= 9)
    caso.complexidade = "Alta";
else
    caso.complexidade = "Muito Alta";

return {
    json: caso
};

// Extrai o bloco de texto do caso de teste (tags, funcionalidade, criticidade
// etc). Antes isso só olhava para "conteudo_atual", o que não funciona para
// casos removidos (que não existem mais na versão atual do arquivo). Agora usa
// "conteudo_referencia": o conteúdo atual para casos novos, e o conteúdo
// anterior (última versão em que o caso existiu) para casos removidos.

const resultado = [];

for (const item of $input.all()) {

    const dados = item.json;

    const codigo = dados.codigo;
    const conteudo = dados.conteudo_referencia || "";

    // Localiza o início do caso de teste
    const inicio = conteudo.indexOf(`@${codigo}`);

    if (inicio === -1) {

        resultado.push({
            json: {
                ...dados,
                erro: "Caso não encontrado no conteúdo de referência."
            }
        });

        continue;
    }

    // Conteúdo a partir do caso encontrado
    const restante = conteudo.substring(inicio + 1);

    // Procura o próximo caso
    // CORREÇÃO: não exige mais um hífen logo após o código do próximo caso
    // (mesmo motivo do ajuste em "Contar Total de Casos do Projeto" e em
    // "Identificar Novos Casos de Teste").
    const proximoCaso = restante.match(/\n@GTPDV-T\d+/);

    let bloco;

    if (proximoCaso) {

        bloco = conteudo.substring(
            inicio,
            inicio + proximoCaso.index + 1
        );

    } else {

        bloco = conteudo.substring(inicio);

    }

    // Extrair linha [Tags]
    const tagsMatch = bloco.match(/\[Tags\](.*)/);

    const tags = tagsMatch
        ? tagsMatch[1]
            .trim()
            .split(/\s{2,}|\t+/)
            .filter(Boolean)
        : [];

    // Funcionalidade
    const funcionalidade =
        tags.find(t =>
            !t.startsWith("GTPDV-") &&
            !["critico","alto","medio","baixo","regressivo-completo","mini-regressivo"].includes(t)
        ) || null;

    // Criticidade
    const criticidade =
        tags.find(t =>
            ["critico","alto","medio","baixo"].includes(t)
        ) || null;

    // Tipos de regressão
    const regressao = tags.filter(t =>
        ["regressivo-completo","mini-regressivo"].includes(t)
    );

    resultado.push({

        json: {

            tipo_mudanca: dados.tipo_mudanca,

            codigo: dados.codigo,

            descricao: dados.descricao,

            caminho_arquivo: dados.caminho_arquivo,

            changeType: dados.changeType,

            commitId_atual: dados.commitId_atual,

            commitId_anterior: dados.commitId_anterior,

            data_commit: dados.data_commit,

            autor: dados.autor,

            comentario_commit: dados.comentario_commit,

            funcionalidade,

            criticidade,

            regressao,

            tags,

            bloco_teste: bloco

        }

    });

}

return resultado;

const itens = $input.all();
const arquivos = [];

for (const item of itens) {
    const dados = item.json;

    const alteracoes = dados.changes || [];

    for (const alteracao of alteracoes) {
        const arquivo = alteracao.item;

        if (!arquivo) {
            continue;
        }

        const caminho = arquivo.path || '';
        const tipoArquivo = arquivo.gitObjectType || '';
        const tipoAlteracao = (alteracao.changeType || '').toLowerCase();

        const ehCaminhoDeTeste =
            caminho.toLowerCase().startsWith('/tests/') &&
            caminho.toLowerCase().endsWith('.robot');

        // Arquivos editados/adicionados: exigimos gitObjectType 'blob' (como antes).
        // Arquivos excluídos: o Azure DevOps nem sempre retorna gitObjectType para
        // itens deletados, então não exigimos essa checagem nesse caso — senão
        // exclusões de suítes inteiras passariam despercebidas pelo fluxo.
        const ehArquivoDeTeste =
            ehCaminhoDeTeste &&
            (
                (['edit', 'add'].includes(tipoAlteracao) && tipoArquivo === 'blob') ||
                tipoAlteracao === 'delete'
            );

        if (ehArquivoDeTeste) {
            arquivos.push({
                json: {
                    commitId: dados.commitId,
                    caminho_arquivo: caminho,
                    objectId_atual: arquivo.objectId,
                    changeType: tipoAlteracao,

                    data_commit: dados.data_commit,
                    autor: dados.autor,
                    comentario_commit: dados.comment
                }
            });
        }
    }
}

return arquivos;

return items.filter(item => {
  const comentario = item.json.comment || '';

  // Descarta commits de Merge do Azure DevOps
  return !comentario.startsWith('Merged PR');
});

// Identifica tanto casos NOVOS (existem agora, não existiam na versão anterior
// do arquivo) quanto casos REMOVIDOS (existiam antes, não existem mais agora).
//
// A comparação é feita pelo código do caso (ex: GTPDV-T28512), que é estável
// mesmo que o nome da suíte/arquivo mude — por isso o resultado não depende do
// nome do arquivo permanecer igual ao longo do tempo.
//
// Cobre os 3 cenários possíveis de um arquivo alterado no período:
//   - Arquivo novo (changeType=add): conteudo_anterior = "" -> todos os casos
//     do arquivo aparecem como "novo".
//   - Arquivo excluído (changeType=delete): conteudo_atual = "" -> todos os
//     casos que existiam no arquivo aparecem como "removido".
//   - Arquivo editado (changeType=edit): comparação normal, caso a caso.

const itens = $input.all();

const resultado = [];

// CORREÇÃO: o hífen logo após o código passou a ser OPCIONAL. Alguns
// casos são nomeados como "GTPDV-T12345 Descrição - Subdescrição" (sem
// hífen logo após o código), e com o hífen obrigatório esses casos nunca
// eram reconhecidos como novos/removidos.
function extrairCasos(conteudo) {
    const encontrados = [
        ...conteudo.matchAll(/^@?(GTPDV-T\d+)\s*-?\s*(.+)$/gm)
    ];

    const mapa = new Map();

    for (const match of encontrados) {
        mapa.set(match[1], match[2].trim());
    }

    return mapa;
}

for (const item of itens) {

    const dados = item.json;

    const conteudoAnterior = dados.conteudo_anterior || '';
    const conteudoAtual = dados.conteudo_atual || '';

    const casosAnteriores = extrairCasos(conteudoAnterior);
    const casosAtuais = extrairCasos(conteudoAtual);

    const metadadosComuns = {
        caminho_arquivo: dados.caminho_arquivo,
        changeType: dados.changeType,
        commitId_atual: dados.commitId_atual,
        commitId_anterior: dados.commitId_anterior,
        data_commit: dados.data_commit,
        autor: dados.autor,
        comentario_commit: dados.comentario_commit
    };

    // ----- Casos novos: existem agora, não existiam antes -----
    for (const [codigo, descricao] of casosAtuais) {

        if (!casosAnteriores.has(codigo)) {

            resultado.push({
                json: {
                    tipo_mudanca: 'novo',
                    codigo,
                    descricao,
                    ...metadadosComuns,
                    conteudo_referencia: conteudoAtual
                }
            });

        }

    }

    // ----- Casos removidos: existiam antes, não existem mais agora -----
    for (const [codigo, descricao] of casosAnteriores) {

        if (!casosAtuais.has(codigo)) {

            resultado.push({
                json: {
                    tipo_mudanca: 'removido',
                    codigo,
                    descricao,
                    ...metadadosComuns,
                    conteudo_referencia: conteudoAnterior
                }
            });

        }

    }

}

return resultado;

// Este nó não confia mais nos campos devolvidos pelas chamadas HTTP de
// "Buscar Conteúdo Atual/Anterior do Arquivo" para identificar o arquivo/commit
// (ex: .path, .commitId), porque quando o arquivo é novo (sem versão anterior)
// ou foi excluído (sem versão atual), essas chamadas retornam erro 404 e não
// trazem esses campos. Em vez disso, a identificação vem sempre de
// "Extrair Commit Pai", que é 100% confiável.
//
// As chamadas HTTP têm "On Error: Continue" configurado, então mesmo em caso de
// 404 o fluxo não é interrompido — o conteúdo simplesmente vem vazio, e é assim
// que sabemos que o arquivo é novo (sem conteúdo anterior) ou foi excluído
// (sem conteúdo atual).

const metadados = $('Extrair Commit Pai').all();
const anteriores = $input.all();
const atuais = $('Buscar Conteúdo Atual do Arquivo').all();

return metadados.map((item, index) => {
    const meta = item.json;
    const anterior = anteriores[index]?.json || {};
    const atual = atuais[index]?.json || {};

    return {
        json: {
            caminho_arquivo: meta.caminho_arquivo,
            changeType: meta.changeType,

            commitId_atual: meta.commitId_atual,
            commitId_anterior: meta.commitId_anterior,

            data_commit: meta.data_commit,
            autor: meta.autor,
            comentario_commit: meta.comentario_commit,

            // Se a busca falhou (arquivo não existia nessa versão), .content
            // vem undefined e cai no fallback de string vazia.
            conteudo_anterior: anterior.content || '',
            conteudo_atual: atual.content || ''
        }
    };
});

const commits = $input.all();

const arquivos = $('Extrair Arquivos Alterados').all();

return commits.map((item, index) => {
    const commit = item.json;
    const arquivo = arquivos[index]?.json || {};

    return {
        json: {
            commitId_atual: commit.commitId,
            commitId_anterior: commit.parents?.[0] || null,

            caminho_arquivo: arquivo.caminho_arquivo,
            changeType: arquivo.changeType,
            objectId_atual: arquivo.objectId_atual,
            objectId_anterior: arquivo.objectId_anterior,

            data_commit: arquivo.data_commit,
            autor: arquivo.autor,
            comentario_commit: arquivo.comentario_commit
        }
    };
});

const resposta = $input.first().json;

const commits = resposta.value || [];

// CORREÇÃO (relatório não saía quando não há commits no período):
// "Separar Commits" é o único nó desta cadeia que SEMPRE executa de verdade
// (alimentado por "Buscar Commits do Período", que sempre entrega 1 item —
// a resposta da API, mesmo que "value" venha vazio). Se não emitirmos nada
// aqui quando commits.length===0, o próximo nó ("Filtrar Commits Reais")
// recebe 0 itens e o n8n pula a execução dele — e isso cascateia por toda a
// cadeia de diff, incluindo nós que fazem chamada HTTP real.
//
// Em vez disso, emitimos 1 item sentinela (comment que não bate com "Merged
// PR", então passa pelo filtro seguinte normalmente). Os nós seguintes já
// são tolerantes a campos ausentes (fallbacks "|| ''"/"|| []"/"?.") e as
// chamadas HTTP dependentes de commitId têm "On Error: Continue" — o
// sentinela flui até "Identificar Novos Casos de Teste", que naturalmente
// não encontra nenhum caso em conteúdo vazio e retorna [] normalmente (sem
// erro). Dali em diante, quem garante que "Preparar Dados para Relatório"
// ainda assim dispare é o Always Output Data em "Enriquecer Caso de Teste".
if (commits.length === 0) {
    return [{
        json: {
            commitId: null,
            comment: '[SEM COMMITS NO PERÍODO]',
            autor: null,
            data_commit: null
        }
    }];
}

return commits.map(commit => ({
  json: {
    commitId: commit.commitId,
    comment: commit.comment,
    autor: commit.author?.name || null,
    data_commit: commit.committer?.date || null
  }
}));

const diasAtras = 7;

const agora = new Date();

// Data inicial: início do dia de X dias atrás
const dataInicio = new Date(agora);
dataInicio.setDate(dataInicio.getDate() - diasAtras);
dataInicio.setHours(0, 0, 0, 0);

// Data final: momento atual
const dataFim = new Date(agora);

return [
  {
    json: {
      dias_atras: diasAtras,
      data_inicio: dataInicio.toISOString(),
      data_fim: dataFim.toISOString(),
      descricao_periodo: `Desde ${diasAtras} dias atrás até agora`
    }
  }
];
